package com.cms.controller; import com.cms.dto.*; import com.cms.service.CategoryService; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/categories") @RequiredArgsConstructor public class CategoryController {private final CategoryService service; @PostMapping @PreAuthorize("hasAnyRole('ADMIN','ACCOUNTANT')") public CategoryResponse create(@Valid @RequestBody CategoryRequest r){return service.create(r);} @GetMapping public List<CategoryResponse> all(){return service.all();}}
